function genStripes(D) {
	stripes = [];

	const num = ~~random(8, 16);
	const xl = random(0.1, 0.3) * width;
	const xr = random(0.7, 0.9) * width;

	const ytm = random(-0.05, -0.1) * height;
	const yld = random(-0.1, 0.15) * height;

	const ybm = (1 - random(-0.05, -0.1)) * height;	
	const yrd = random(-0.1, 0.15) * height;

	box = {
		x1: xl, x2: xr, y1: ytm, y2: ybm
	}

	for (let i = 0; i < num; i++) {
		const f = i / (num - 1);
		const x1 = -D;
		const y1 = lerp(ytm - yld, ybm + yld, f);
		const x2 = xl;
		const y2 = lerp(ytm, ybm, f);
		const x3 = xr;
		const y3 = lerp(ytm, ybm, f);
		const x4 = width + D;
		const y4 = lerp(ytm - yrd, ybm + yrd, f);

		const st = [
			{x: x1, y: y1},
			{x: x2, y: y2},
			{x: x3, y: y3},
			{x: x4, y: y4},
		]

		stripes.push(st);
	}

	return stripes;
}


function easy(f) {
  const v1 = f * f;
  const v2 = sqrt(f);
  const vv = lerp(v2, v1, f)
  return vv;
}

function randomClrArea(ar) {
	const t = frameCount / 60;

	const n1 = noise(ar.i, t) + 0.1;
	const n2 = noise(ar.j/10, t) -0.1;
	const n3 = noise((ar.i + ar.j)/10, t);

	// const clr = color(n1 * 255 + 100, n2 * 160, n3 * 255);
	const clr1 = color("#69C"); // base color
	const clr2 = color(n1 * 255, n2 * 255, n3 * 255); // gen color

	const nn = noise(t, (ar.j)/10); // for lerp between base color and generated color
	const clr = lerpColor(clr1, clr2, pow(nn+0.25, 2.5));

	const CLRS = [color("navy"), clr1, clr2]
	const { EpiColors } = EpiColorsPckg;
	epiColors = new EpiColors([CLRS]);
	return epiColors.getLerpedColorFromPalette(easy(nn));

	return clr;
}


function interpPoint(pa, pb, x) {
	const t = (x - pa.x) / (pb.x - pa.x);
	const y = lerp(pa.y, pb.y, t)
	return {x: ~~x, y: ~~y};
}

function sliceStripe(stripe, xStart, xEnd) {
  if (xEnd < xStart) [xStart, xEnd] = [xEnd, xStart];

  // optional: clamp an Stripe-Grenzen
  xStart = max(xStart, stripe[0].x);
  xEnd   = min(xEnd, stripe[stripe.length - 1].x);

  // Index für Segment, in dem xStart liegt
  let iStart = 0;
  for (let i = 0; i < stripe.length - 1; i++) {
    if (stripe[i].x <= xStart && xStart <= stripe[i + 1].x) {
      iStart = i;
      break;
    }
  }

  // Index für Segment, in dem xEnd liegt
  let iEnd = stripe.length - 2;
  for (let i = 0; i < stripe.length - 1; i++) {
    if (stripe[i].x <= xEnd && xEnd <= stripe[i + 1].x) {
      iEnd = i;
      break;
    }
  }

  const result = [];

  // Startpunkt (interpoliert)
  const pStart = interpPoint(stripe[iStart], stripe[iStart + 1], xStart);
  result.push(pStart);

  // alle original Punkte dazwischen, die wirklich innerhalb (xStart, xEnd) liegen
  for (let i = iStart + 1; i <= iEnd; i++) {
    const p = stripe[i];
    if (p.x > xStart && p.x < xEnd) {
      result.push(p);
    }
  }

  // Endpunkt (interpoliert)
  const pEnd = interpPoint(stripe[iEnd], stripe[iEnd + 1], xEnd);
  result.push(pEnd);

  return result; // von links nach rechts
}


function splitAreaBetween(stripeTop, stripeBottom, xStart, xEnd) {
  const topPts = sliceStripe(stripeTop, xStart, xEnd);         // links → rechts
  const bottomPts = sliceStripe(stripeBottom, xStart, xEnd);   // links → rechts
  bottomPts.reverse();                                        // rechts → links

  return topPts.concat(bottomPts); // Polygon im Uhrzeigersinn
}

// Compute bounding box
function computeBox(a) {
	let x1 = Infinity, x2 = -Infinity, y1 = Infinity, y2 = -Infinity;
	for (const p of a) {
		x1 = Math.min(x1, p.x);
		x2 = Math.max(x2, p.x);
		y1 = Math.min(y1, p.y);
		y2 = Math.max(y2, p.y);
	}
	return { x1, x2, y1, y2 };
}

function genAreas(stripes, D=0) {
	areas = [];

	for (let i = 0; i < stripes.length - 1; i++) {
		const st1 = stripes[i];
		const st2 = stripes[i + 1];
		const num = ~~(noise(i) * 3) + 3;
		const wdt = (width+D+D)/num;
		for (let j = 0, xStart = -D; j < num; j++) {
			const ns = noise(i, j, frameCount/60);
			// const xWidth = ~~(random(0.9, 1.1) * wdt);
			const xWidth = ~~(map(ns, 0, 1, 0.8, 1.2) * wdt);
			let xEnd = xStart + xWidth;
			if (j === num-1) xEnd = width+D;
			const pts = splitAreaBetween(st1, st2, xStart, xEnd)
			const box = computeBox(pts);
			areas.push({pts, box, i, j});
			xStart = xEnd;
		}
	}

	return areas;
}

