// --- helpers ---

function jitter(v) {
  return v + (Math.random() * 0.6 - 0.3); // [-0.3, 0.3]
}

// remove closing duplicate if present
function stripClosingPoint(pts) {
  if (pts.length > 1) {
    const first = pts[0];
    const last  = pts[pts.length - 1];
    if (first.x === last.x && first.y === last.y) {
      return pts.slice(0, -1);
    }
  }
  return pts;
}

// add closing duplicate if missing
function closePolygon(pts) {
  if (!pts.length) return pts;
  const first = pts[0];
  const last  = pts[pts.length - 1];
  if (first.x !== last.x || first.y !== last.y) {
    pts.push({ x: first.x, y: first.y });
  }
  return pts;
}

// remove consecutive duplicate points in an OPEN polygon
function dedupeConsecutive(pts) {
  if (pts.length <= 1) return pts;
  const out = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    const a = out[out.length - 1];
    const b = pts[i];
    if (a.x !== b.x || a.y !== b.y) {
      out.push(b);
    }
  }
  return out;
}

// compute bounding box from an OPEN polygon (no closing duplicate)
function computeBoxOpen(pts) {
  let x1 = Infinity, x2 = -Infinity;
  let y1 = Infinity, y2 = -Infinity;
  for (const p of pts) {
    if (p.x < x1) x1 = p.x;
    if (p.x > x2) x2 = p.x;
    if (p.y < y1) y1 = p.y;
    if (p.y > y2) y2 = p.y;
  }
  return { x1, x2, y1, y2 };
}

// generic Sutherland–Hodgman clipping
// isInside(p) -> boolean
// intersect(S, E) -> intersection point with the splitting line (assumed to exist when called)
function clipPolygon(ptsOpen, isInside, intersect) {
  const input = ptsOpen;
  let output = [];

  if (input.length === 0) return output;

  const n = input.length;
  let S = input[n - 1]; // start with last as S

  for (let i = 0; i < n; i++) {
    const E = input[i];
    const S_in = isInside(S);
    const E_in = isInside(E);

    if (E_in) {
      if (S_in) {
        // inside -> inside: keep E
        output.push(E);
      } else {
        // outside -> inside: add intersection, then E
        const I = intersect(S, E);
        if (I) output.push(I);
        output.push(E);
      }
    } else {
      if (S_in) {
        // inside -> outside: add intersection only
        const I = intersect(S, E);
        if (I) output.push(I);
      } else {
        // outside -> outside: add nothing
      }
    }

    S = E;
  }

  return dedupeConsecutive(output);
}

// --- vertical split helper ---
function splitVerticalOpen(ptsOpen, cx) {
  const eps = 1e-9;

  // left: x <= cx
  const leftOpen = clipPolygon(
    ptsOpen,
    (p) => p.x <= cx + eps,
    (S, E) => {
      const dx = E.x - S.x;
      if (Math.abs(dx) < eps) return null; // vertical edge -> no intersection
      const t = (cx - S.x) / dx;
      if (t < 0 || t > 1) return null;
      return {
        x: cx,
        y: S.y + t * (E.y - S.y),
      };
    }
  );

  // right: x >= cx
  const rightOpen = clipPolygon(
    ptsOpen,
    (p) => p.x >= cx - eps,
    (S, E) => {
      const dx = E.x - S.x;
      if (Math.abs(dx) < eps) return null;
      const t = (cx - S.x) / dx;
      if (t < 0 || t > 1) return null;
      return {
        x: cx,
        y: S.y + t * (E.y - S.y),
      };
    }
  );

  return { leftOpen, rightOpen };
}

// --- horizontal split helper ---
function splitHorizontalOpen(ptsOpen, cy) {
  const eps = 1e-9;

  // top: y <= cy
  const topOpen = clipPolygon(
    ptsOpen,
    (p) => p.y <= cy + eps,
    (S, E) => {
      const dy = E.y - S.y;
      if (Math.abs(dy) < eps) return null; // horizontal edge
      const t = (cy - S.y) / dy;
      if (t < 0 || t > 1) return null;
      return {
        x: S.x + t * (E.x - S.x),
        y: cy,
      };
    }
  );

  // bottom: y >= cy
  const bottomOpen = clipPolygon(
    ptsOpen,
    (p) => p.y >= cy - eps,
    (S, E) => {
      const dy = E.y - S.y;
      if (Math.abs(dy) < eps) return null;
      const t = (cy - S.y) / dy;
      if (t < 0 || t > 1) return null;
      return {
        x: S.x + t * (E.x - S.x),
        y: cy,
      };
    }
  );

  return { topOpen, bottomOpen };
}

// --- main function: split area horizontally OR vertically around center ---

function splitArea(area) {
  const { pts, box, i: baseI = 0, j: baseJ = 0 } = area;

  // work with OPEN polygon internally
  const open = stripClosingPoint(pts);
  if (open.length < 3) return []; // nothing to split

  const cx = ~~lerp(box.x1, box.x2, random(0.3, 0.7));
  const cy = ~~lerp(box.y1, box.y2, random(0.3, 0.7));

  const horizontal = Math.random() < 0.5;

  let openA1 = [];
  let openA2 = [];

  if (horizontal) {
    const { topOpen, bottomOpen } = splitHorizontalOpen(open, cy);
    openA1 = topOpen;
    openA2 = bottomOpen;
  } else {
    const { leftOpen, rightOpen } = splitVerticalOpen(open, cx);
    openA1 = leftOpen;
    openA2 = rightOpen;
  }

  const result = [];

  function makeAreaFromOpen(openPts) {
    if (!openPts || openPts.length < 3) return null; // need at least 3 unique points

    const box = computeBoxOpen(openPts);
    const closed = closePolygon(openPts.slice()); // copy & close

    return {
      pts: closed,
      box,
      i: jitter(baseI),
      j: jitter(baseJ),
    };
  }

  const a1 = makeAreaFromOpen(openA1);
  const a2 = makeAreaFromOpen(openA2);

  if (a1) result.push(a1);
  if (a2) result.push(a2);

  return result;
}



