let D = 20;
let stripes, areas, box;

OPC.toggle('shakeScene', false);
OPC.toggle('animTiles', false);

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("areas of splitted horizontal lines with changing illumination");
	frameRate(30);

	stripes = genStripes(D);
	areas = genAreas(stripes, D);

	noFill();
	noStroke();
	strokeWeight(2);

	D = max(width, height) * 0.1;

	loop();
}

function draw() {
	if (random() < 0.05) doSplit();

	background(6, 6, 16);
	noStroke();
	fill("#036");
	rect(0, 0, width, ~~(height / 2));

	if (animTiles) areas = genAreas(stripes, D);

	const t = frameCount / 10;
	const tx = (noise(t, 100) - 0.5) * D;
	const ty = (noise(t, 200) - 0.5) * D;
	if (shakeScene) translate(tx, ty);

	// inner tiles / areas
	stroke(16, 16, 64, 32);
	noStroke();
	strokeWeight(1);
	for (const ar of areas) {
		fill(randomClrArea(ar));
		beginShape();
		for (const p of ar.pts) vertex(p.x, p.y);
		endShape();
		// inner tiles gllow
		if (ar.pts.length === 4) {
			makeGlow(ar);
		}
	}

	// stripes
	stroke(0, 128);
	noFill();
	for (const st of stripes) {
		beginShape();
		for (const p of st) vertex(p.x, p.y + 2);
		endShape();
	}
	stroke(255);
	for (const st of stripes) {
		beginShape();
		for (const p of st) vertex(p.x, p.y);
		endShape();
	}

	push()
	noStroke()
	fill(255, 32);
	rect(box.x1, box.y1, box.x2 - box.x1, box.y2 - box.y1);
	pop();
}

function doSplit() {
	const idx = ~~random(areas.length);
	const newAreas = splitArea(areas[idx]);
	// newAreas[0], newAreas[1] are the two smaller areas (if both exist)
	if (!newAreas.length) return;

	if (newAreas && newAreas.length == 2) {
		areas.push(newAreas[0]);
		areas.push(newAreas[1]);
		areas.splice(idx, 1);
	}
}

function makeGlow(ar) {
	return;
	if (ar.pts.length !== 4) return;
	const cx = lerp(ar.pts[0].x, ar.pts[1].x, 0.5);
	const cy = lerp(ar.pts[0].y, ar.pts[3].y, 0.5);
	push();
	noStroke();
	fill(255, 32);
	circle(cx, cy, 100);
	pop();
}

function mousePressed() {
	if (!mouseButton.right) setup();
}
